<script setup lang="ts">
/**
 * Navigation as text, with an optional Button-styled variant (`design/components/link.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/link.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, useTemplateRef } from 'vue'

import { Icon, agentMember, agentPress, useListening } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/link.module.css'

export type LinkVariant = NonNullable<LinkProps['variant']>

export interface LinkButtonGrid {
  solid: 'accent'
  soft: 'accent'
  outline: 'accent' | 'neutral'
  ghost: 'accent' | 'neutral'
}

export interface LinkProps {
  buttonVariant?: 'solid' | 'soft' | 'outline' | 'ghost'
  /**
   * Adds the glyph, the new tab, and the `rel` that makes it safe.
   */
  external?: boolean
  href: string
  /**
   * Control size, as on Button.
   */
  size?: 'sm' | 'md' | 'lg'
  tone?: 'accent' | 'neutral'
  /**
   * `inline` sits inside a sentence and `standalone` is a row or a title.
   */
  variant?: 'inline' | 'standalone' | 'button'
}

defineOptions({ name: 'Link', inheritAttrs: false })

const props = withDefaults(defineProps<LinkProps>(), {
  buttonVariant: 'soft',
  external: false,
  size: 'md',
  tone: 'accent',
  variant: 'inline',
})
const emit = defineEmits<{ navigate: [href: string] }>()
defineSlots<{ default: (props: Record<string, never>) => unknown }>()
const listening = useListening()
const control = useTemplateRef<HTMLElement>('control')
const navigatesHere = computed(
  () =>
    (event: MouseEvent): boolean =>
      !event.defaultPrevented &&
      event.button === 0 &&
      !event.metaKey &&
      !event.ctrlKey &&
      !event.shiftKey &&
      !event.altKey,
)
const route = computed(() => (event: MouseEvent): void => {
  if (props.external || !navigatesHere.value(event)) return
  event.preventDefault()
  emit('navigate', props.href)
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'Link',
    element: () => control.value,
    state: () => ({ external: props.external }),
    actions: {
      press: () =>
        (() => {
          if (props.external)
            throw new Error('An external link opens a new tab, which only a person’s press opens.')
          agentPress(control.value)
        })(),
    },
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <a
    v-if="variant === 'button'"
    ref="control"
    :class="styles.costume"
    :href="href"
    :data-variant="buttonVariant"
    :data-tone="tone"
    :data-size="size"
    :data-external="external ? '' : undefined"
    :target="external ? '_blank' : undefined"
    :rel="external ? 'noreferrer' : undefined"
    data-member="link"
    @click="listening.navigate && route($event)"
  >
    <!-- label -->
    <span :class="styles.costumeLabel">
      <slot />
    </span>
    <!-- glyph -->
    <span v-if="external" :class="styles.costumeGlyph">
      <Icon name="open-external" :size="size" />
    </span>
  </a>
  <a
    v-else
    ref="control"
    :class="styles.link"
    :href="href"
    :data-variant="variant"
    :data-external="external ? '' : undefined"
    :target="external ? '_blank' : undefined"
    :rel="external ? 'noreferrer' : undefined"
    data-member="link"
    @click="listening.navigate && route($event)"
  >
    <slot />
    <Icon v-if="external" name="open-external" size="sm" />
  </a>
</template>
